Literal.Value:
'{
  "$schema": "https://vega.github.io/schema/vega/v6.json",
  "description": "Raincloud plot of yearly growth in active doctors per Fachgruppe (cloud = density, box = quartiles, rain = years).",
  "data": [
    {
      "name": "dataset"
    },
    {
      "name": "growth",
      "source": "dataset",
      "transform": [
        {
          "type": "filter",
          "expr": "isValid(datum[''Doctor Growth YoY'']) && isFinite(datum[''Doctor Growth YoY''])"
        },
        {
          "type": "formula",
          "as": "g",
          "expr": "datum[''Doctor Growth YoY'']"
        },
        {
          "type": "formula",
          "as": "jitter",
          "expr": "((datum[''Year''] * 7) % 16) / 15"
        },
        {
          "type": "extent",
          "field": "g",
          "signal": "gExtent"
        }
      ]
    },
    {
      "name": "stats",
      "source": "growth",
      "transform": [
        {
          "type": "aggregate",
          "groupby": [
            "fachgruppe"
          ],
          "fields": [
            "g",
            "g",
            "g",
            "g",
            "g",
            "g"
          ],
          "ops": [
            "min",
            "q1",
            "median",
            "q3",
            "max",
            "count"
          ],
          "as": [
            "min",
            "q1",
            "median",
            "q3",
            "max",
            "n"
          ]
        }
      ]
    },
    {
      "name": "density",
      "source": "growth",
      "transform": [
        {
          "type": "kde",
          "groupby": [
            "fachgruppe"
          ],
          "field": "g",
          "steps": 120,
          "extent": {
            "signal": "[gExtent[0] - 0.03, gExtent[1] + 0.03]"
          },
          "as": [
            "value",
            "density"
          ]
        },
        {
          "type": "joinaggregate",
          "fields": [
            "density"
          ],
          "ops": [
            "max"
          ],
          "as": [
            "maxDensity"
          ]
        },
        {
          "type": "lookup",
          "from": "stats",
          "key": "fachgruppe",
          "fields": [
            "fachgruppe"
          ],
          "values": [
            "min",
            "max"
          ],
          "as": [
            "groupMin",
            "groupMax"
          ]
        },
        {
          "type": "filter",
          "expr": "datum.value >= datum.groupMin && datum.value <= datum.groupMax"
        }
      ]
    }
  ],
  "scales": [
    {
      "name": "x",
      "type": "linear",
      "range": "width",
      "nice": true,
      "zero": false,
      "domain": {
        "signal": "[min(0, gExtent[0] - 0.03), gExtent[1] + 0.03]"
      }
    },
    {
      "name": "y",
      "type": "band",
      "range": "height",
      "paddingInner": 0.12,
      "paddingOuter": 0.04,
      "domain": {
        "data": "stats",
        "field": "fachgruppe",
        "sort": {
          "field": "median",
          "op": "max",
          "order": "descending"
        }
      }
    }
  ],
  "axes": [
    {
      "orient": "bottom",
      "scale": "x",
      "format": ".0%",
      "grid": true,
      "tickCount": 8,
      "zindex": 0,
      "title": "Year-on-year growth in active doctors (2010–2025)"
    },
    {
      "orient": "left",
      "scale": "y",
      "ticks": false,
      "domain": false,
      "labelPadding": 8,
      "labelLimit": 220,
      "labelFontSize": 11,
      "labelColor": "#0b0b0b"
    }
  ],
  "marks": [
    {
      "type": "rule",
      "encode": {
        "update": {
          "x": {
            "scale": "x",
            "value": 0
          },
          "y": {
            "value": 0
          },
          "y2": {
            "signal": "height"
          },
          "stroke": {
            "value": "#898781"
          },
          "strokeDash": {
            "value": [
              4,
              3
            ]
          },
          "strokeWidth": {
            "value": 1
          }
        }
      }
    },
    {
      "type": "group",
      "name": "clouds",
      "from": {
        "facet": {
          "name": "cloud",
          "data": "density",
          "groupby": "fachgruppe"
        }
      },
      "encode": {
        "update": {
          "y": {
            "scale": "y",
            "field": "fachgruppe"
          },
          "height": {
            "scale": "y",
            "band": 1
          },
          "width": {
            "signal": "width"
          }
        }
      },
      "marks": [
        {
          "type": "area",
          "from": {
            "data": "cloud"
          },
          "encode": {
            "update": {
              "x": {
                "scale": "x",
                "field": "value"
              },
              "y": {
                "signal": "bandwidth(''y'') * 0.55"
              },
              "y2": {
                "signal": "bandwidth(''y'') * 0.55 * (1 - datum.density / datum.maxDensity)"
              },
              "fill": {
                "value": "#2a78d6"
              },
              "fillOpacity": {
                "value": 0.3
              },
              "stroke": {
                "value": "#2a78d6"
              },
              "strokeWidth": {
                "value": 1.2
              },
              "interpolate": {
                "value": "monotone"
              }
            }
          }
        }
      ]
    },
    {
      "type": "rule",
      "from": {
        "data": "stats"
      },
      "encode": {
        "update": {
          "x": {
            "scale": "x",
            "field": "min"
          },
          "x2": {
            "scale": "x",
            "field": "max"
          },
          "y": {
            "scale": "y",
            "field": "fachgruppe",
            "offset": {
              "signal": "bandwidth(''y'') * 0.66"
            }
          },
          "stroke": {
            "value": "#52514e"
          },
          "strokeWidth": {
            "value": 1
          },
          "tooltip": {
            "signal": "{''Fachgruppe'': datum.fachgruppe, ''Median growth'': format(datum.median, ''.1%''), ''Middle 50 %'': format(datum.q1, ''.1%'') + '' to '' + format(datum.q3, ''.1%''), ''Lowest / highest year'': format(datum.min, ''.1%'') + '' / '' + format(datum.max, ''.1%''), ''Years'': datum.n}"
          }
        }
      }
    },
    {
      "type": "rect",
      "from": {
        "data": "stats"
      },
      "encode": {
        "update": {
          "x": {
            "scale": "x",
            "field": "q1"
          },
          "x2": {
            "scale": "x",
            "field": "q3"
          },
          "y": {
            "scale": "y",
            "field": "fachgruppe",
            "offset": {
              "signal": "bandwidth(''y'') * 0.6"
            }
          },
          "height": {
            "signal": "bandwidth(''y'') * 0.12"
          },
          "fill": {
            "value": "#fcfcfb"
          },
          "stroke": {
            "value": "#52514e"
          },
          "strokeWidth": {
            "value": 1
          },
          "cornerRadius": {
            "value": 2
          },
          "tooltip": {
            "signal": "{''Fachgruppe'': datum.fachgruppe, ''Median growth'': format(datum.median, ''.1%''), ''Middle 50 %'': format(datum.q1, ''.1%'') + '' to '' + format(datum.q3, ''.1%''), ''Lowest / highest year'': format(datum.min, ''.1%'') + '' / '' + format(datum.max, ''.1%''), ''Years'': datum.n}"
          }
        }
      }
    },
    {
      "type": "rect",
      "from": {
        "data": "stats"
      },
      "encode": {
        "update": {
          "xc": {
            "scale": "x",
            "field": "median"
          },
          "width": {
            "value": 2.5
          },
          "y": {
            "scale": "y",
            "field": "fachgruppe",
            "offset": {
              "signal": "bandwidth(''y'') * 0.58"
            }
          },
          "height": {
            "signal": "bandwidth(''y'') * 0.16"
          },
          "fill": {
            "value": "#0b0b0b"
          },
          "tooltip": {
            "signal": "{''Fachgruppe'': datum.fachgruppe, ''Median growth'': format(datum.median, ''.1%''), ''Middle 50 %'': format(datum.q1, ''.1%'') + '' to '' + format(datum.q3, ''.1%''), ''Lowest / highest year'': format(datum.min, ''.1%'') + '' / '' + format(datum.max, ''.1%''), ''Years'': datum.n}"
          }
        }
      }
    },
    {
      "type": "symbol",
      "from": {
        "data": "growth"
      },
      "encode": {
        "update": {
          "x": {
            "scale": "x",
            "field": "g"
          },
          "y": {
            "scale": "y",
            "field": "fachgruppe",
            "offset": {
              "signal": "bandwidth(''y'') * (0.79 + 0.17 * datum.jitter)"
            }
          },
          "size": {
            "value": 30
          },
          "fill": [
            {
              "test": "datum.g < 0",
              "value": "#e34948"
            },
            {
              "value": "#2a78d6"
            }
          ],
          "fillOpacity": {
            "value": 0.8
          },
          "stroke": {
            "value": "#ffffff"
          },
          "strokeWidth": {
            "value": 0.5
          },
          "tooltip": {
            "signal": "{''Fachgruppe'': datum.fachgruppe, ''Year'': datum[''Year''], ''Growth'': format(datum.g, ''.1%''), ''Active doctors (year end)'': format(datum[''Active Doctors (Year End)''], '','')}"
          }
        }
      }
    }
  ]
}'
